var paymentInputs=document.querySelectorAll("#payment .form-check input[type=radio]");if(paymentInputs){paymentInputs.forEach(item=>{item.addEventListener("click",function(evt){document.querySelectorAll(".payment-option",evt.target).forEach(item=>{item.style.display="none"}),evt.target.parentNode.parentNode.querySelectorAll(".payment-option").forEach(item=>{item.style.display="block"})})});let paymentSelector=document.querySelector("#payment");paymentSelector&&paymentSelector.addEventListener("submit",function(){replaceHistoryFromPreviousStep()})}let shipSelect=document.querySelector('select[name="sShipSet"]');shipSelect&&shipSelect.addEventListener("change",function(){replaceHistoryFromPreviousStep(),this.form.submit()});